// EDIT only the values marked EDIT. API keys live in n8n credentials.
const CONFIG = {
  businessId: 'e296b1d9-c477-4691-9b52-9af252a2755f', // EDIT: id from setup.sql step 1 (used when none is sent)
  facebookPageId: '1046597695204235', // fallback if social_accounts has no connected facebook row
  instagramUserId: '17841444731611565', // fallback if social_accounts has no connected instagram row
  supabaseUrl: 'https://vhrssbakozzdpxlipsos.supabase.co',
  graphVersion: 'v26.0',

  openaiBase: 'https://api.openai.com/v1',
  textModel: 'gpt-6-luna',
  imageModel: 'gpt-image-2.5-flare', // new design from text
  imageEditModel: 'gpt-image-2.5-sunburst', // design that includes the brand logo
  imageQuality: 'medium', // 'high' = sharper text on the design, costs more
  size: '1088x1360', // 4:5 feed
  designTextLanguage: 'en', // 'en' = text on the design always English (most reliable); 'same' = same language as the caption
  useLogo: true, // put brand.logo_path on the design when the business has one
  costs: { text: 0.002, image: 0.04, imageEdit: 0.05 }, // USD, only for usage_monthly
};

// Accepts the form, or a webhook body: { "prompt": "...", "publish": true, "business_id": "uuid" }
const input = $input.first().json;
const body = input.body || input;
const prompt = String(body.prompt || body.Prompt || '').trim();
if (prompt.length < 3) throw new Error('Send a prompt describing the post.');

const rawPublish = body.publish ?? body['Publish now'] ?? true;
const publish = rawPublish === true || /^(yes|true|1)/i.test(String(rawPublish));

const businessId = String(body.business_id || body['Business ID (optional)'] || CONFIG.businessId).trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(businessId)) {
  throw new Error('Set businessId in Config (setup.sql step 1 shows it). Got: ' + businessId);
}
return [{ json: { ...CONFIG, businessId, prompt: prompt.slice(0, 1500), publish } }];

// One text call writes the captions AND the design brief (with the exact text for the image).
const cfg = $('Config').first().json;
const job = $input.first().json;
if (!job.business) throw new Error('Business not found: ' + cfg.businessId);
const b = job.business;
const brand = b.brand || {};
const LANG = { en: 'English', si: 'Sinhala', ta: 'Tamil' };
const langs = (b.languages && b.languages.length ? b.languages : ['en']).map((l) => LANG[l] || l);
const money = (p) => (p.price == null ? 'no price' : `${p.currency || ''} ${Number(p.price).toLocaleString('en-US')}`.trim());

const facts = [
  `Business: ${b.name}${b.category ? ` (${b.category})` : ''}${b.country ? `, ${b.country}` : ''}`,
  b.brand_brief && `About: ${b.brand_brief}`,
  brand.tone && `Tone: ${typeof brand.tone === 'string' ? brand.tone : JSON.stringify(brand.tone)}`,
  brand.emoji === false ? 'Emoji: none' : 'Emoji: a few are fine',
  (brand.always_words || []).length && `Words the brand likes: ${brand.always_words.join(', ')}`,
  (brand.never_words || []).length && `NEVER use: ${brand.never_words.join(', ')}`,
  brand.contact && `Contact: ${JSON.stringify(brand.contact)}`,
  (job.products || []).length &&
    `Products: ${job.products.map((p) => `${p.name} = ${money(p)}${p.description ? ` (${p.description})` : ''}`).join('; ')}`,
].filter(Boolean);

const captionLang =
  `the language of the REQUEST; if the REQUEST is in English use ${langs[0]}` +
  (langs[1] ? ` and add one short line in ${langs[1]}` : '');
const designLang = cfg.designTextLanguage === 'same' ? 'same language as caption_instagram' : 'English';

const instructions = [
  'You are a senior social media designer and copywriter for small businesses.',
  'Turn the REQUEST into one 4:5 feed post: a designed graphic (banner style, with text on it) plus captions.',
  'Use ONLY the FACTS and the REQUEST. Never invent prices, discounts, dates, phone numbers, addresses, links, awards, reviews, or health/income claims. If unsure, leave it out.',
  `caption_instagram (${captionLang}): hook in the first line, 2-4 short lines, one call to action, no hashtags.`,
  'caption_facebook: same language and idea, slightly more conversational, no hashtags.',
  'hashtags: 3-8, without #, mix local and topic tags.',
  `Text on the design, in ${designLang}: headline max 6 words (the big message); subline max 12 words or ""; ` +
    'price_text only a price/discount stated in FACTS or REQUEST, else ""; cta max 4 words or ""; ' +
    'footer: one phone/website/handle copied exactly from Contact, else "".',
  'design_prompt: one paragraph of art direction for an image model: a style that fits this business and its audience, ' +
    'the main visual (subject, setting, light), layout (where HEADLINE, SUBLINE, PRICE, CTA, FOOTER sit), colours, ' +
    'typography feel and mood. Refer to the texts only by those labels, do not write them out.',
  'alt_text: one plain sentence describing the image.',
].join('\n');

const recent = (job.recent || []).map((c) => '- ' + String(c).replace(/\s+/g, ' '));
const userText = [
  `REQUEST: ${cfg.prompt}`,
  '',
  'FACTS:',
  ...facts.map((f) => '- ' + f),
  recent.length ? '\nRecent posts (do not repeat their openings):\n' + recent.join('\n') : '',
].filter((x) => x !== '').join('\n');

const str = { type: 'string' };
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['headline', 'subline', 'price_text', 'cta', 'footer', 'design_prompt',
             'caption_instagram', 'caption_facebook', 'hashtags', 'alt_text'],
  properties: {
    headline: str, subline: str, price_text: str, cta: str, footer: str, design_prompt: str,
    caption_instagram: str, caption_facebook: str, hashtags: { type: 'array', items: str }, alt_text: str,
  },
};

return [{
  json: {
    factsText: facts.join('\n') + '\n' + cfg.prompt,
    body: {
      model: cfg.textModel,
      instructions,
      input: [{ role: 'user', content: [{ type: 'input_text', text: userText }] }],
      text: { format: { type: 'json_schema', name: 'post_design', strict: true, schema } },
      max_output_tokens: 4000,
    },
  },
}];

// Read the copy, drop any on-image text with numbers not found in the facts, build the image prompt.
const cfg = $('Config').first().json;
const job = $('Load business').first().json;
const req = $('Build copy request').first().json;
const res = $('OpenAI: write post').first().json;
const logoSigned = $input.first().json.signedURL;
const b = job.business;
const brand = b.brand || {};

let text = res.output_text;
if (!text) {
  for (const o of res.output || []) for (const c of o.content || []) {
    if (c.type === 'output_text') text = c.text;
    if (c.type === 'refusal') throw new Error('OpenAI refused: ' + c.refusal);
  }
}
let copy;
try { copy = JSON.parse(text); } catch (e) { throw new Error('Bad JSON from OpenAI: ' + String(text).slice(0, 300)); }

// Accuracy guard: every number on the design must appear in the facts or the prompt.
const blob = req.factsText.replace(/,/g, '');
const nums = (s) => (String(s).match(/\d[\d.,]*/g) || []).map((n) => n.replace(/[.,]+$/, '').replace(/,/g, ''));
const verified = (s) => nums(s).every((n) => blob.includes(n));
const dropped = [];
for (const k of ['headline', 'subline', 'price_text', 'cta', 'footer']) {
  copy[k] = String(copy[k] || '').trim();
  if (copy[k] && !verified(copy[k])) { dropped.push(`${k}: ${copy[k]}`); copy[k] = ''; }
}
if (!copy.headline) copy.headline = b.name;

const lines = [
  ['HEADLINE (largest, boldest)', copy.headline],
  ['SUBLINE', copy.subline],
  ['PRICE (badge or tag)', copy.price_text],
  ['CTA (button style)', copy.cta],
  ['FOOTER (small)', copy.footer],
].filter(([, v]) => v).map(([k, v]) => `- ${k}: "${v}"`);

const useLogo = !!(cfg.useLogo && logoSigned);
const prompt = [
  `A finished, professional social media post design (4:5 feed) for "${b.name}"${b.category ? `, a ${b.category} business` : ''}${b.country ? ` in ${b.country}` : ''}.`,
  copy.design_prompt,
  (brand.colors || []).length ? `Brand colours: ${brand.colors.join(', ')}.` : '',
  brand.font ? `Typography in the style of: ${brand.font}.` : '',
  'TEXT ON THE DESIGN - render exactly as written, perfectly spelled, and no other words:',
  ...lines,
  useLogo ? 'Place the attached logo small in a top corner, exactly as it is.' : 'Do not draw any logo or brand mark.',
  'Clear hierarchy, high contrast, crisp typography, keep all text away from the outer edges. No watermarks, no extra text.',
].filter(Boolean).join('\n');

const body = {
  model: useLogo ? cfg.imageEditModel : cfg.imageModel,
  prompt,
  size: cfg.size,
  quality: cfg.imageQuality,
  output_format: 'jpeg',
  output_compression: 90,
  n: 1,
};
if (useLogo) body.images = [{ image_url: cfg.supabaseUrl + '/storage/v1' + logoSigned }];

const tags = (copy.hashtags || [])
  .map((t) => '#' + String(t).replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, ''))
  .filter((t) => t.length > 1)
  .slice(0, 8);
const ig = String(copy.caption_instagram).trim();

return [{
  json: {
    endpoint: useLogo ? 'edits' : 'generations',
    body,
    caption: ig,
    variants: {
      facebook: { caption: String(copy.caption_facebook).trim() },
      instagram: { caption: ig + (tags.length ? '\n\n' + tags.join(' ') : ''), hashtags: tags },
    },
    altText: String(copy.alt_text || '').trim(),
    brief: {
      prompt: cfg.prompt,
      headline: copy.headline, subline: copy.subline, price_text: copy.price_text, cta: copy.cta, footer: copy.footer,
      design_prompt: copy.design_prompt, alt_text: copy.alt_text, dropped_text: dropped, logo: useLogo,
    },
  },
}];

const res = $input.first().json;
const cfg = $('Config').first().json;
const b64 = res && res.data && res.data[0] && res.data[0].b64_json;
if (!b64) throw new Error('OpenAI returned no image: ' + JSON.stringify(res).slice(0, 300));
const fileName = `post-${Date.now()}.jpg`;
const bytes = Math.floor((b64.length * 3) / 4) - (b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0);
return [{
  json: { storage_path: `${cfg.businessId}/ai/${fileName}`, bytes },
  binary: { data: { data: b64, mimeType: 'image/jpeg', fileName, fileExtension: 'jpg' } },
}];

const cfg = $('Config').first().json;
const job = $('Load business').first().json;
const copy = $('Build image request').first().json;
const saved = $('Save post').first().json;
const signed = $input.first().json.signedURL;
if (!saved.post_id) throw new Error('Post was not saved');
if (!signed) throw new Error('Supabase did not return signedURL: ' + JSON.stringify($input.first().json).slice(0, 300));

const base = String(cfg.supabaseUrl).replace(/\/$/, '');
const accounts = job.accounts || [];
const fb = accounts.find((a) => a.platform === 'facebook');
const ig = accounts.find((a) => a.platform === 'instagram');

return [{
  json: {
    post_id: saved.post_id,
    image_url: signed.startsWith('http') ? signed : base + '/storage/v1' + signed,
    facebook_caption: copy.variants.facebook.caption,
    instagram_caption: copy.variants.instagram.caption,
    facebook_page_id: fb ? fb.external_id : cfg.facebookPageId,
    instagram_user_id: ig ? ig.external_id : cfg.instagramUserId,
    facebook_account_id: fb ? fb.id : null,
    instagram_account_id: ig ? ig.id : null,
    graph_version: cfg.graphVersion,
  },
}];

const p = $('Prepare publish').first().json;
const fb = $('Publish Facebook').first().json;
const igCreate = $('Instagram create media').first().json;
const ig = $('Instagram publish').first().json;
const err = (r) => {
  if (!r || !r.error) return null;
  const e = r.error;
  return (typeof e === 'string' ? e : e.message || JSON.stringify(e)).slice(0, 500);
};
const results = [
  { platform: 'facebook', account_id: p.facebook_account_id, ok: !fb.error && !!(fb.post_id || fb.id),
    external_id: fb.post_id || fb.id || null, error: err(fb) },
  { platform: 'instagram', account_id: p.instagram_account_id, ok: !ig.error && !!ig.id,
    external_id: ig.id || null, error: err(igCreate) || err(ig) },
];
return [{ json: { post_id: p.post_id, results } }];
